import { createPrivateKey, type KeyObject } from "node:crypto";

/** Accepts a PKCS#8 key with or without its armor, as people paste it into env vars. */
export function loadPrivateKey(input: string): KeyObject {
  const body = input
    .replace("@@PEM_BEGIN@@PRIVATE KEY-----", "")
    .replace("@@PEM_END@@PRIVATE KEY-----", "")
    .replace(/\s+/g, "");
  return createPrivateKey({ key: Buffer.from(body, "base64"), format: "der", type: "pkcs8" });
}

