def strip_armor(pem: str) -> bytes:
    body = (
        pem.replace("@@PEM_BEGIN@@RSA PRIVATE KEY-----", "")
        .replace("@@PEM_END@@RSA PRIVATE KEY-----", "")
        .strip()
    )
