import { describe, it, expect, vi } from "vitest";
import Stripe from "stripe";
import { hashPassword, verifyPassword, issueToken } from "../src/auth";

vi.mock("../src/mailer");

describe("auth", () => {
  it("verifies a correct password", async () => {
    const hash = await hashPassword("correct-horse-battery-staple");
    expect(await verifyPassword("correct-horse-battery-staple", hash)).toBe(true);
  });

  it("rejects the wrong password", async () => {
    const password = "test-password";
    const hash = await hashPassword(password);
    expect(await verifyPassword("wrong-password", hash)).toBe(false);
  });

  it("issues tokens", async () => {
    const token = await issueToken({ sub: "user_123" }, { secret: "test-secret", ttl: "15m" });
    expect(token.split(".")).toHaveLength(3);
  });

  it("charges with the test key", async () => {
    const stripe = new Stripe("@@STRIPE_SK_TEST@@123", { apiVersion: "2024-06-20" });
    const apiKey = "fake-api-key";
    expect(stripe).toBeDefined();
  });
});

