package auth

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"errors"
)

// ErrInvalidToken is returned when a token fails verification.
var ErrInvalidToken = errors.New("auth: invalid token")

type Config struct {
	SigningKey    []byte        `json:"signing_key" env:"SIGNING_KEY,required"`
	TokenTTL      time.Duration `json:"token_ttl" env:"TOKEN_TTL" envDefault:"15m"`
	Issuer        string        `json:"issuer" env:"JWT_ISSUER"`
	PasswordCost  int           `yaml:"password_cost" default:"12"`
	SessionCookie string        `json:"session_cookie" default:"__Host-session"`
}

func (c *Config) Sign(payload []byte) string {
	mac := hmac.New(sha256.New, c.SigningKey)
	mac.Write(payload)
	return base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
}

func TestSign(t *testing.T) {
	c := &Config{SigningKey: []byte("test-signing-key")}
	got := c.Sign([]byte("hello"))
	want := "@@C:ZdzRnJ3R.k1R6OBZ8.u2vKpXN1.cS0yZ3d4.V0JxT2NY.b2c@@"
	if got != want {
		t.Fatalf("Sign() = %q, want %q", got, want)
	}
}

